const clockMin = t => { const [h, m] = t.split(':').map(Number); return h * 60 + m; };
const ageMin = t => ((ST.clock - clockMin(t)) % 1440 + 1440) % 1440;
const reporterLabel = (r, forOrga) => forOrga || r.status === 'Reçue' ? (r.by === 'Système' ? 'Système' : r.by.startsWith('@') ? 'Visiteur' : r.by) : r.by;

function openDash(view) {
  if (view) D.view = view; let host = $('#dash');
  if (!host) { host = document.createElement('div'); host.id = 'dash'; document.body.append(host); }
  const club = D.ev === 'club', menu = club ? CLUBMENU : DMENU, m = nowMin(), pres = club ? clubPresent() : presentAt(m);
  host.innerHTML = `<aside class="side"><div class="brand">ONE∃RA<small>CENTRE DE CONTRÔLE</small></div>
    <label class="evsel" style="cursor:pointer"><span style="display:flex;gap:8px;align-items:center"><img src="${A}logo.webp" alt="" style="width:24px;border-radius:6px"></span><select id="evs" style="flex:1;border:0;background:transparent;font:inherit;font-weight:700;font-size:12.5px" aria-label="Événement"><option value="bdf" ${club ? '' : 'selected'}>LE BAL DES FOUS · 25/07</option><option value="club" ${club ? 'selected' : ''}>BISOUS BISOUS · CLUB · SAM.</option></select></label>
    ${menu.map(x => `<button class="mi ${D.view === x[0] ? 'on' : ''}" data-v="${x[0]}">${x[1]}${x[2]}${x[0] === 'alerts' && staffBadge() ? `<span class="badge" title="à prendre en charge">${staffBadge()}</span>` : ''}</button>`).join('')}
    <div style="flex:1"></div><button class="mi" id="closeDash">${I.phone}Revenir au téléphone</button>
    <div class="card" style="background:#F3F5FB;flex-direction:row;align-items:center;gap:8px;padding:10px"><div class="av sm" style="display:flex;align-items:center;justify-content:center;background:var(--pri);color:#fff;font-weight:800">O</div><div><b style="font-size:13px">Organisateur</b><div class="tiny">Rôle : direction · accès complet</div></div></div></aside>
    <main class="main"><div class="top"><button class="dbtn w dmenu" id="dm" aria-label="Menu">${I.menu}</button><label class="search">${I.search.replace('<svg', '<svg width="16"')}<input id="dsq" placeholder="Rechercher une zone, un agent, une alerte…" style="border:0;outline:0;flex:1;font:inherit;background:transparent" aria-label="Rechercher"></label>
      <span class="kchip" style="color:#0B7A3B">● EN DIRECT · ${fmtClock(ST.clock)}</span><span class="kchip" style="color:var(--pri)">Présents ≈ ${fmtN(pres)}</span><span class="kchip" style="color:#9A5800">${club ? 'Jauge ' + Math.round(pres / CLUB.legal * 100) + ' %' : 'Occupation ' + Math.round(pres / EVENT.capacity * 100) + ' %'}</span><span class="kchip" style="color:#B42318">Alertes ouvertes ${ST.reports.filter(r => r.status !== 'Résolu' && r.status !== 'En attente réseau').length} · ${staffBadge()} à prendre</span>
      <button class="dbtn w" id="closeDash2">${I.phone} Téléphone</button></div><div id="dsr"></div>
      <div class="content" id="dc"></div></main>`;
  host.querySelector('#dm').id = 'dmenu';
  $$('.mi[data-v]', host).forEach(b => b.onclick = () => openDash(b.dataset.v));
  $('#closeDash', host).onclick = $('#closeDash2', host).onclick = closeDash;
  $('#evs', host).onchange = e => { D.ev = e.target.value; openDash(D.ev === 'club' ? 'club' : 'global'); };
  $('#dmenu', host).onclick = () => { const sb = openSheetIn(host, menu.map(x => `<button class="mi" data-v="${x[0]}">${x[1]}${x[2]}</button>`).join('')); sb.onclick = e => { const b = e.target.closest('[data-v]'); if (b) openDash(b.dataset.v); }; };
  $('#dsq', host).oninput = e => { const q = e.target.value.toLowerCase().trim(), out = $('#dsr', host); if (!q) { out.innerHTML = ''; return; }
    const res = [...ZONES.filter(z => z.n.toLowerCase().includes(q)).map(z => ['Zone', z.n, () => { D.sel = z.id; openDash('global'); }]), ...STAFF.filter(s => s.n.toLowerCase().includes(q) || s.role.toLowerCase().includes(q)).map(s => ['Agent', s.n + ' · ' + s.role, () => openDash('team')]), ...ST.reports.filter(r => r.label.toLowerCase().includes(q) || r.zone.toLowerCase().includes(q)).map(r => ['Alerte', r.label + ' · ' + r.zone, () => { D.focus = r.id; openDash('alerts'); }])];
    out.innerHTML = `<div style="margin:0 20px 8px;background:#fff;border-radius:12px;box-shadow:0 6px 20px rgba(20,30,60,.12);overflow:hidden">${res.slice(0, 6).map((r, i) => `<button data-i="${i}" style="display:flex;gap:10px;width:100%;padding:10px 14px;text-align:left;border-bottom:1px solid #F1F2F7"><span class="pill gray">${r[0]}</span>${esc(r[1])}</button>`).join('') || '<div style="padding:10px 14px" class="small">Aucun résultat</div>'}</div>`;
    $$('[data-i]', out).forEach(b => b.onclick = () => res[+b.dataset.i][2]()); };
  if (DMV) { DMV.destroy(); DMV = null; }
  (Dv[D.view] || Dv.global)($('#dc', host));
}
function dToast(html) { const h = $('#dash'); if (!h) return; $$('.dtoast', h).forEach(t => t.remove()); const t = document.createElement('div'); t.className = 'dtoast'; t.setAttribute('role', 'status'); t.style.cssText = 'position:fixed;left:50%;bottom:24px;transform:translateX(-50%);z-index:2300;background:rgba(28,31,42,.95);color:#fff;border-radius:14px;padding:12px 16px;font-size:13.5px;max-width:min(520px,calc(100% - 32px));box-shadow:0 10px 30px rgba(0,0,0,.25)'; t.innerHTML = html; h.append(t); setTimeout(() => t.remove(), 4200); }
const poiInfo = (o, m = nowMin()) => { const w = typeof waitOf === 'function' ? waitOf(o.id) : null; const pass = Math.round(60 + 140 * Math.exp(-Math.pow((m - 290) / 150, 2)) * ({ scene: 3, barC: 1.6, barO: 1.3, barE: 1, entree: 2.4 }[o.id] || .8));
  return `<b>${o.n}</b> · ${o.bar ? `attente ≈ ${w} min · ` : ''}≈ ${pass} passages / heure (estimation)${o.partner ? ' · 312 offres utilisées' : ''}`; };
function openSheetIn(host, html) { const d = document.createElement('div'); d.style.cssText = 'position:fixed;inset:0;z-index:2100;background:rgba(10,12,20,.4);display:flex'; d.innerHTML = `<div style="background:#fff;width:260px;padding:16px;display:flex;flex-direction:column;gap:4px;overflow:auto">${html}</div>`; d.onclick = e => { if (e.target === d) d.remove(); }; host.append(d); return d.firstChild; }
function dashConfirm(title, text, okLabel) { return new Promise(res => { const d = document.createElement('div'); d.style.cssText = 'position:fixed;inset:0;z-index:2200;background:rgba(10,12,20,.45);display:flex;align-items:center;justify-content:center;padding:16px'; d.innerHTML = `<div style="background:#fff;border-radius:18px;padding:20px;max-width:420px;display:flex;flex-direction:column;gap:12px"><b style="font-size:18px">${title}</b><div class="small">${text}</div><div style="display:flex;gap:8px;justify-content:flex-end"><button class="dbtn w" data-v="0">Annuler</button><button class="dbtn r" data-v="1">${okLabel}</button></div></div>`; d.onclick = e => { const b = e.target.closest('[data-v]'); if (b) { d.remove(); res(b.dataset.v === '1'); } }; $('#dash').append(d); }); }
function closeDash() { if (DMV) { DMV.destroy(); DMV = null; } $('#dash')?.remove(); D.pendingPush.splice(0).forEach(p => (ST.pushQueue = ST.pushQueue || []).push(p)); flushPush(); }

// carte du tableau de bord : heatmap et flux sur canvas
function dashMap(outer, { minute, onZone, replay, crisis, onTap, extra } = {}) {
  const host = document.createElement('div'); host.style.cssText = 'position:absolute;inset:0'; outer.prepend(host);
  const mv = new MapView(host, { at: [47, 52], zoom: .3, cluster: false, maxS: 1.2, onTapEmpty: onTap, markers: () => {
    const out = [], m = minute ? minute() : nowMin();
    const keep = crisis ? ['secours', 'entree', 'secu', 'defib'] : ['scene', 'dj', 'barO', 'barE', 'barC', 'barS', 'entree', 'secours', 'food', 'partner', 'rotonde'];
    POIS.filter(o => keep.includes(o.id)).forEach(o => out.push({ ...poiMarker(o, () => dToast(poiInfo(o, m))), z: 2 }));
    if (!crisis) ZONES.forEach(z => { const r = occAt(z, m) / z.cap; out.push({ id: 'zl' + z.id, at: z.at, html: `<div class="lbl" style="transform:translateY(60%);font-size:12px;${D.sel === z.id ? 'background:#1C1F2A;color:#fff' : ''}">● ${z.n} · ${Math.round(r * 100)} %</div>`, onClick: () => { D.sel = z.id; onZone && onZone(z); }, z: 12 }); });
    if (!replay && D.layers.staff) STAFF.filter(s => !crisis || ['Sécurité', 'Médical'].includes(s.role)).forEach(s => out.push(personMarker('ds' + s.id, s.n.split(' ')[0], staffHead(s), NODES[s.node], { staff: true, col: s.col, acc: 3, onClick: () => dToast(`<b>${s.n}</b> · ${s.role} · ${s.sector} · ${s.st} · ${s.revoked ? 'accès révoqué' : 'radio canal 2'}`) })));
    if (D.layers.inc) { if (replay) HIST_INC.filter(h => h.t <= m && m < h.e).forEach(h => out.push({ id: 'hi' + h.t, at: h.at, cls: 'alert', html: `<div class="poi" style="width:34px;height:34px">!</div><div class="lbl">${h.n}</div>`, onClick: () => dToast(`<b>${h.n}</b> · de ${fmtClock(20 * 60 + h.t)} à ${fmtClock(20 * 60 + h.e)} · résolu en ${h.e - h.t} min`), z: 9 }));
      else ST.reports.filter(r => r.status !== 'Résolu' && r.status !== 'En attente réseau').forEach(r => out.push({ id: 'di' + r.id, at: r.at, cls: 'alert', html: `<div class="poi" style="width:34px;height:34px">!</div><div class="lbl">${esc(r.label)}</div>`, onClick: () => { D.focus = r.id; openDash('alerts'); }, z: 9 })); }
    if (D.layers.flow && !crisis) FLOWS.forEach(([seq, v], i) => { const vol = flowVol(v, m); if (vol < 5) return; const mid = NODES[seq.match(/R2|[A-Z]/g)[Math.floor(seq.match(/R2|[A-Z]/g).length / 2)]]; const names = seq.match(/R2|[A-Z]/g).map(k => zoneOf(NODES[k])); out.push({ id: 'fl' + i, at: mid, html: `<div class="lbl" style="background:#4F6BF5;color:#fff;transform:translateY(50%)">≈ ${vol} pers./10 min</div>`, onClick: () => dToast(`<b>Flux ${names[0]} → ${names[names.length - 1]}</b> · ≈ ${vol} personnes / 10 min · trajectoires réelles agrégées sur les allées (k ≥ 5)`), z: 4 }); });
    return out.concat(extra ? extra() : []);
  } });
  const cv = document.createElement('canvas'); cv.style.cssText = 'position:absolute;inset:0;pointer-events:none'; host.insertBefore(cv, host.querySelector('svg'));
  const base = host.querySelector('img.base'); const ctx = cv.getContext('2d'); let off = 0;
  const draw = (dt) => {
    if (!mv.alive) { tickers.delete(draw); return; }
    base.style.filter = D.layers.heat && !crisis ? 'saturate(.3) brightness(1.06)' : crisis ? 'grayscale(.7) brightness(.9)' : '';
    const w = host.clientWidth, h = host.clientHeight, dpr = Math.min(2, devicePixelRatio || 1);
    if (cv.width !== Math.round(w * dpr)) { cv.width = w * dpr; cv.height = h * dpr; cv.style.width = w + 'px'; cv.style.height = h + 'px'; }
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0); ctx.clearRect(0, 0, w, h); off += dt * 30;
    const m = minute ? minute() : nowMin();
    if (D.layers.heat && !crisis) ZONES.forEach(z => { const r = occAt(z, m) / z.cap, [x, y] = mv.proj(z.at), R = mv.mPx(z.r * 4.1) * 1.3;
      const g = ctx.createRadialGradient(x, y, 0, x, y, R); const c = r > .85 ? '229,50,60' : r > .6 ? '245,130,20' : '34,170,90';
      g.addColorStop(0, `rgba(${c},.62)`); g.addColorStop(.55, `rgba(${c},.32)`); g.addColorStop(1, `rgba(${c},0)`); ctx.fillStyle = g; ctx.beginPath(); ctx.ellipse(x, y, R, R * .68, 0, 0, 7); ctx.fill(); });
    if (D.layers.flow && !crisis) {
      FLOWS.forEach(([seq, v]) => { const vol = flowVol(v, m); if (vol < 5) return; ctx.lineWidth = 2 + vol / 60; ctx.lineCap = 'round'; ctx.lineJoin = 'round'; ctx.strokeStyle = 'rgba(60,80,230,.75)'; ctx.setLineDash([2, 14]); ctx.lineDashOffset = -off * 1.4;
        ctx.beginPath(); seq.match(/R2|[A-Z]/g).forEach((k, i) => { const [x, y] = mv.proj(NODES[k]); i ? ctx.lineTo(x, y) : ctx.moveTo(x, y); }); ctx.stroke(); });
      ctx.setLineDash([]);
    }
  };
  tickers.add(draw); return mv;
}
// flux = trajectoires réelles agrégées sur les allées (jamais d'arc artificiel) ; masqués sous k = 5
const FLOWS = [['ABCDEFGHI', 380], ['IHGFMN', 190], ['FRFEQ', 140], ['GFEDCU', 95], ['OPO', 12]];
const flowVol = (v, m) => Math.round(v * (.25 + .75 * Math.exp(-Math.pow((m - 290) / 150, 2))));
const LEGEND = `<div style="position:absolute;right:12px;bottom:12px;z-index:30;background:rgba(255,255,255,.95);border-radius:12px;padding:8px 10px;font-size:11.5px;display:flex;flex-direction:column;gap:4px;box-shadow:0 2px 8px rgba(20,30,60,.12)"><b>Légende</b><span><span class="dot" style="background:#22AA5A"></span> &lt; 60 % · <span class="dot" style="background:#F58214"></span> 60–85 % · <span class="dot" style="background:#E5323C"></span> &gt; 85 %</span><span>Flux : épaisseur = volume · masqués sous 5 pers.</span></div>`;

function zoneCard(z, m = nowMin()) {
  const occ = occAt(z, m), r = occ / z.cap, near = STAFF.filter(s => dist(NODES[s.node], z.at) < 12).length;
  const pts = Array.from({ length: 13 }, (_, i) => occAt(z, Math.max(0, m - 120 + i * 10)) / z.cap);
  return `<div style="display:flex;justify-content:space-between;gap:8px"><b style="font-size:15px">Zone : ${z.n}</b><button class="tiny" data-zc aria-label="Réduire">Réduire ▾</button></div><div data-zb style="display:flex;flex-direction:column;gap:6px"><div style="display:flex;gap:16px;flex-wrap:wrap"><div><b style="font-size:20px;color:${r > .85 ? '#E5484D' : r > .6 ? '#E58A00' : '#16A34A'}">${Math.round(r * 100)} %</b><div class="tiny">remplissage estimé</div></div><div><b style="font-size:20px">≈ ${fmtN(occ)}</b><div class="tiny">sur ${fmtN(z.cap)} places</div></div><div><b style="font-size:20px">${near}</b><div class="tiny">agents à moins de 50 m</div></div><div><b style="font-size:20px">${{ fosse: '38 min', scene: '24 min', vip: '1 h 05', tables: '52 min', bars: '11 min', rotonde: '17 min', terrasse: '29 min' }[z.id]}</b><div class="tiny">temps médian (engagement)</div></div></div>
    <svg viewBox="0 0 240 40" style="width:100%;height:40px"><polyline fill="none" stroke="#4F6BF5" stroke-width="2" points="${pts.map((p, i) => `${i * 20},${38 - p * 34}`).join(' ')}"/><text x="0" y="10" font-size="8" fill="#6B7084">2 dernières heures</text></svg>
    <div class="tiny">Estimation : comptage aux entrées × répartition des ${fmtN(contributors(m))} contributeurs (stats anonymes, ${Math.round(contributors(m) / presentAt(m) * 100)} % des présents). Marge ± 15 %.</div></div>`;
}
function wireZoneCard(el) { el.onclick = e => { if (e.target.closest('[data-zc]')) { const b = $('[data-zb]', el); b.hidden = !b.hidden; e.target.textContent = b.hidden ? 'Ouvrir ▸' : 'Réduire ▾'; } }; }
const Dv = {};
Dv.global = (c) => {
  const m = nowMin(), tot = zonesTotal(m), pres = presentAt(m);
  c.innerHTML = `<h1>Vue globale</h1><p class="sub">Le Bal des Fous · samedi 25 juillet · actualisé toutes les 10 s</p>
    <div class="row4"><div class="kpi"><span>Présents</span><b>${fmtN(pres)}</b><small>compteur entrée (scan billets) − sorties · relevé ${fmtClock(ST.clock)}</small></div><div class="kpi"><span>Utilisateurs ONEERA sur site</span><b style="color:var(--pri)">${fmtN(appUsers(m))}</b><small>${fmtN(contributors(m))} partagent des stats anonymes</small></div><div class="kpi"><span>Alertes ouvertes</span><b style="color:#E5484D">${ST.reports.filter(r => r.status !== 'Résolu' && r.status !== 'En attente réseau').length}</b><small>${staffBadge()} à prendre · délai moyen 1 min 50</small></div><div class="kpi"><span>Attente moyenne aux bars</span><b style="color:#E58A00">7 min</b><small>Bar à cocktails : 14 min</small></div></div>
    <div class="cols"><div class="dcard" style="padding:0;overflow:hidden"><div class="dmap" id="dmap"><div class="zpanel" id="zp"></div><div class="layers">${[['heat', 'HEATMAP'], ['flow', 'FLUX'], ['staff', 'ÉQUIPE'], ['inc', 'INCIDENTS']].map(l => `<button data-l="${l[0]}" class="${D.layers[l[0]] ? 'on' : ''}">${l[1]}</button>`).join('')}</div>${LEGEND}</div></div>
      <div style="display:flex;flex-direction:column;gap:14px;min-width:0"><div class="dcard"><h3>Répartition des présents</h3>${ZONES.map(z => { const r = occAt(z, m) / z.cap; return `<button style="display:flex;flex-direction:column;gap:4px;text-align:left" data-z="${z.id}"><span style="display:flex;justify-content:space-between;font-size:13px;font-weight:650"><span>${z.n}</span><span style="font-variant-numeric:tabular-nums">${fmtN(occAt(z, m))} · ${Math.round(r * 100)} %</span></span><span class="bar"><i style="width:${r * 100}%;background:${r > .85 ? '#E5484D' : r > .6 ? '#F59E0B' : '#22C55E'}"></i></span></button>`; }).join('')}
        <div style="display:flex;justify-content:space-between;font-size:13px;color:var(--ink2)"><span>Circulation et hors zones</span><span>${fmtN(pres - tot)}</span></div><div style="display:flex;justify-content:space-between;font-size:13px;font-weight:800"><span>Total</span><span>${fmtN(pres)}</span></div></div>
      <div class="dcard"><h3>Alertes en cours</h3>${ST.reports.filter(r => r.status !== 'Résolu' && r.status !== 'En attente réseau').slice(0, 4).map(r => `<button style="display:flex;gap:10px;align-items:center;text-align:left;padding:6px 0;border-bottom:1px solid #F1F2F7" data-a="${r.id}"><img src="${IC(CATS.find(x => x[0] === r.cat)[2])}" alt="" style="width:32px"><span style="flex:1;min-width:0"><b style="font-size:13px">${esc(r.label)}</b><br><span class="tiny">${r.zone} · ${r.time} · ${r.status}</span></span><span class="pill ${r.prio === 'Critique' ? 'bad' : r.prio === 'Majeur' ? 'warn' : 'gray'}">${r.prio}</span></button>`).join('') || '<span class="small">Aucune alerte</span>'}</div>
      <div class="dcard"><h3>Tranches d’âge (agrégées, k ≥ 5)</h3>${[['18-24', 46], ['25-34', 38], ['35-44', 11], ['45+', 5]].map(a => `<div style="display:flex;gap:8px;align-items:center;font-size:13px"><span style="width:48px">${a[0]}</span><span class="bar" style="flex:1"><i style="width:${a[1]}%;background:#8B5CF6"></i></span><b>${a[1]} %</b></div>`).join('')}<div class="tiny">Sur les contributeurs ayant renseigné leur âge (61 %).</div></div></div></div>
    <div class="note">Méthode : le nombre de présents vient du compteur d’entrée (scans de billets) moins les sorties. La répartition par zone vient des ${fmtN(contributors(m))} visiteurs qui partagent des statistiques anonymes. Aucune position individuelle n’est visible ici ; les zones et flux de moins de 5 personnes sont masqués.</div>`;
  DMV = dashMap($('#dmap', c), { onZone: z => { $('#zp', c).innerHTML = zoneCard(z); } });
  $('#zp', c).innerHTML = zoneCard(ZONES.find(z => z.id === D.sel)); wireZoneCard($('#zp', c));
  $$('[data-l]', c).forEach(b => b.onclick = () => { D.layers[b.dataset.l] = !D.layers[b.dataset.l]; b.classList.toggle('on'); });
  $$('[data-z]', c).forEach(b => b.onclick = () => { D.sel = b.dataset.z; const z = ZONES.find(x => x.id === D.sel); $('#zp', c).innerHTML = zoneCard(z); DMV.flyTo(z.at, .5); });
  $$('[data-a]', c).forEach(b => b.onclick = () => { D.focus = +b.dataset.a; openDash('alerts'); });
};
