function suggestAgents(r) {
  const want = r.cat === 'medical' ? ['Médical', 'Sécurité'] : r.cat === 'lost' ? ['Manager', 'Sécurité'] : ['Sécurité', 'Manager'];
  return STAFF.filter(s => want.includes(s.role) && !s.revoked).map(s => ({ ...s, d: metersPath(route(s.node, nearestNode(r.at)), NODES[s.node]) })).sort((a, b) => (a.st !== 'Dispo') - (b.st !== 'Dispo') || want.indexOf(a.role) - want.indexOf(b.role) || a.d - b.d).slice(0, 3);
}
