  const side = () => { const m = minute(); $('#hh', c).textContent = fmtClock(20 * 60 + m); const act = HIST_INC.filter(h => h.t <= m && m < h.e);
    $('#side', c).innerHTML = `<h3>À ${fmtClock(20 * 60 + m)}</h3><div class="row4" style="grid-template-columns:1fr 1fr"><div class="kpi" style="background:#F6F7FB;padding:10px"><span>Présents</span><b style="font-size:20px">${fmtN(presentAt(m))}</b></div><div class="kpi" style="background:#F6F7FB;padding:10px"><span>Entrées / 10 min</span><b style="font-size:20px">${fmtN(Math.max(0, (presentAt(m) - presentAt(Math.max(0, m - 10))) + 30))}</b></div></div>
      ${ZONES.map(z => { const r = occAt(z, m) / z.cap; return `<div style="display:flex;flex-direction:column;gap:3px"><span style="display:flex;justify-content:space-between;font-size:13px"><span>${z.n}</span><b>${Math.round(r * 100)} %</b></span><span class="bar"><i style="width:${r * 100}%;background:${r > .85 ? '#E5484D' : r > .6 ? '#F59E0B' : '#22C55E'}"></i></span></div>`; }).join('')}
      <div class="small"><b>Flux principal :</b> Entrée → Fosse ≈ ${flowVol(380, m)} pers./10 min</div><div class="small"><b>Incidents en cours :</b> ${act.map(h => h.n).join(', ') || 'aucun'}</div><div class="small"><b>Sur scène :</b> ${LINEUP.find(l => l.s === 'scene' && toMin20(l.f) <= m && m < toMin20(l.t))?.a || '—'}</div>`; };
  const mv0 = DMV; const tk = dt => { if (!mv0.alive) { tickers.delete(tk); return; } if (playing) { D.replayK = Math.min(1, D.replayK + dt * speed / 480); $('#sl', c).value = minute(); if (D.replayK >= 1) playing = false; side(); } };
  tickers.add(tk); side();
