Dv.club = (c) => {
  const p = clubPresent(), r = p / CLUB.legal, q = Array.from({ length: 16 }, (_, i) => ({ t: fmtClock(23 * 60 + i * 15 - 240 + 240), e: Math.round(40 * Math.exp(-Math.pow((i - 7) / 3.5, 2)) + 6), s: Math.round(6 + i * 1.6) }));
  c.innerHTML = `<h1>Bisous Bisous · samedi</h1><p class="sub">Lieu permanent · soirée récurrente n° 31 · jauge réglementaire ${CLUB.legal} personnes</p>
    <div class="row4"><div class="kpi" style="${r > .9 ? 'background:#FDECEC' : ''}"><span>Jauge réglementaire</span><b style="color:${r > .9 ? '#E5484D' : r > .75 ? '#E58A00' : '#16A34A'}">${fmtN(p)} / ${CLUB.legal}</b><small>${Math.round(r * 100)} % · alerte automatique à 90 %</small></div><div class="kpi"><span>Entrées ce soir</span><b>${fmtN(p + 186)}</b><small>scanner porte · relevé ${fmtClock(ST.clock)}</small></div><div class="kpi"><span>Tables réservées occupées</span><b>21 / 26</b></div><div class="kpi"><span>File vestiaire</span><b>≈ 6 min</b></div></div>
    <div class="cols"><div class="dcard" style="padding:0;overflow:hidden"><div class="dmap" id="cm" style="height:480px;background:#fff"></div></div>
      <div style="display:flex;flex-direction:column;gap:14px;min-width:0"><div class="dcard"><h3>Porte : entrées et sorties par quart d’heure</h3><svg viewBox="0 0 320 120" style="width:100%">${q.map((x, i) => `<rect x="${i * 20 + 2}" y="${100 - x.e * 2}" width="8" height="${x.e * 2}" fill="#4F6BF5" rx="2"/><rect x="${i * 20 + 10}" y="${100 - x.s * 2}" width="8" height="${x.s * 2}" fill="#E58A00" rx="2"/>`).join('')}<text x="0" y="116" font-size="9" fill="#6B7084">23:00</text><text x="140" y="116" font-size="9" fill="#6B7084">01:00</text><text x="280" y="116" font-size="9" fill="#6B7084">03:00</text></svg><div class="tiny"><span class="dot" style="background:#4F6BF5"></span> entrées · <span class="dot" style="background:#E58A00"></span> sorties</div></div>
      <div class="dcard"><h3>Par espace</h3>${CLUB.zones.map(z => { const o = Math.round(z.cap * Math.min(.97, r * z.w * 1.1)); return `<div style="display:flex;flex-direction:column;gap:3px"><span style="display:flex;justify-content:space-between;font-size:13px"><span>${z.n}</span><b>${o} / ${z.cap}</b></span><span class="bar"><i style="width:${o / z.cap * 100}%;background:${o / z.cap > .85 ? '#E5484D' : '#22C55E'}"></i></span></div>`; }).join('')}</div></div></div>
    <div class="note">Logique club : la même carte sert toutes les semaines. Chaque soirée est comparée automatiquement à la précédente (menu « Semaine N-1 »). Deux niveaux : le casino et le club sont séparés, une personne au casino n’apparaît jamais dans le club.</div>`;
  DMV = new MapView($('#cm', c), { src: A + 'bisous.webp', w: 1200, h: 800, at: [52, 48], zoom: .5, cluster: false, maxS: 1.6, markers: () => CLUB.zones.map(z => { const o = Math.round(z.cap * Math.min(.97, r * z.w * 1.1)); return { id: 'cz' + z.id, at: z.at, html: `<div class="lbl" style="font-size:12px">● ${z.n} · ${Math.round(o / z.cap * 100)} %</div>`, halo: { m: 30, c: o / z.cap > .85 ? '#E5484D' : '#F59E0B' }, onClick: () => dToast(`<b>${z.n}</b> · ${o} / ${z.cap} personnes · temps moyen ${['42', '58', '12', '26', '4'][CLUB.zones.indexOf(z)]} min`), z: 3 }; }) });
};
Dv.clubcmp = (c) => {
  c.innerHTML = `<h1>Semaine N-1</h1><p class="sub">Samedi soir vs samedi précédent, à la même heure</p>
    <div class="row4"><div class="kpi"><span>Entrées à ${fmtClock(ST.clock)}</span><b>${fmtN(clubPresent() + 186)} <small style="color:#0B7A3B">+12 %</small></b></div><div class="kpi"><span>Pic de jauge</span><b>91 % <small style="color:#B42318">+4 pts</small></b><small>à 01:40 la semaine dernière</small></div><div class="kpi"><span>Temps moyen</span><b>2 h 48 <small style="color:#0B7A3B">+9 min</small></b></div><div class="kpi"><span>Incidents</span><b>3 <small style="color:#0B7A3B">−2</small></b></div></div>
    <div class="dcard"><h3>Tendance sur 8 semaines (entrées par soirée)</h3><svg viewBox="0 0 400 140" style="width:100%">${[612, 655, 590, 702, 688, 731, 745, 836].map((v, i) => `<rect x="${i * 48 + 10}" y="${130 - v / 7}" width="30" height="${v / 7}" rx="4" fill="${i === 7 ? '#4F6BF5' : '#C9D3FB'}"/><text x="${i * 48 + 25}" y="${124 - v / 7}" font-size="10" text-anchor="middle" fill="#1C1F2A">${v}</text>`).join('')}</svg></div>`;
};
